.progress-bar-order-step{
    width: 120px;
    border-radius: 50%;
    border: 1px solid #47B2FF;
    background: #FFF;
    display: inline-block;
}

.step-num{

    vertical-align: middle;
    color: #47B2FF;
    text-align: center;
    font-family: Inter;
    font-size: 18px;
    font-style: normal;
    font-weight: 600;
    line-height: normal;
}

.smaller-font{
    font-size: 14px;

}

.start-step{
    border-radius: 50px;
    border: 1px solid #47B2FF;
    background: #47B2FF;
    display: inline-flex;
    padding: 13px;
    align-items: flex-start;
    gap: 10px;
}

.notes-title{

    margin-top: 2em;
    color: #000;
    font-family: Nunito;
    font-size: 20px;
    font-style: normal;
    font-weight: 200;
    line-height: normal;
    text-transform: uppercase;
}

.notes-box{
    border: black 1px solid;
    height: 20vh;
}

#title{
    color: #000;
    text-align: center;
    font-family: Nunito;
    font-size: 48px;
    font-style: normal;
    font-weight: 200;
    line-height: normal;
    text-transform: uppercase;
}

.customer-interactions-btn{
    border-radius: 50px;
    background: #064BEC;
    color: #FFF !important;
    font-family: Nunito;
    font-size: 20px;
    font-style: normal;
    font-weight: 200;
    line-height: normal;
}